const owner={id:'owner',name:'Synthetic owner',role:'owner'},viewer={id:'viewer',name:'Synthetic viewer',role:'viewer'};
const results=[],failures=[],networkAttempts=[];let passed=0;
const priorFetch=globalThis.fetch;globalThis.fetch=async(...args)=>{networkAttempts.push(String(args[0]));throw Error('No network allowed in polish regression.');};
async function test(name,fn){try{const details=await fn();passed++;results.push({name,passed:true,...(details||{})});}catch(error){failures.push({name,error:error.message,stack:String(error.stack||'').slice(0,1600)});results.push({name,passed:false,error:error.message});}}
const query=values=>new URLSearchParams(Object.entries(values).filter(([,value])=>value!==undefined).map(([key,value])=>[key,String(value)])).toString();
function harness(){
 const sqlite=new DatabaseSync(':memory:');sqlite.exec('PRAGMA foreign_keys=ON');for(const name of readdirSync(new URL('../migrations/',import.meta.url)).filter(name=>/^\d{4}_.+\.sql$/.test(name)).sort())sqlite.exec(readFileSync(new URL('../migrations/'+name,import.meta.url),'utf8'));
 let insideBatch=false,afterRead=null;const trace=[];
 const execute=(sql,values)=>{const stmt=sqlite.prepare(sql);trace.push({sql,values});const result=stmt.columns().length?{success:true,results:stmt.all(...values),meta:{changes:0}}:(()=>{const info=stmt.run(...values);return{success:true,results:[],meta:{changes:Number(info.changes)}};})();if(afterRead&&!insideBatch&&stmt.columns().length){const action=afterRead;afterRead=null;action();}return result;};
 const db={prepare(sql){return{sql,values:[],bind(...values){this.values=values;assert.ok(values.length<=100);return this;},async first(column){const row=execute(sql,this.values).results[0]||null;return column&&row?row[column]:row;},async all(){return execute(sql,this.values);},async run(){return execute(sql,this.values);}};},async batch(statements){sqlite.exec('BEGIN IMMEDIATE');insideBatch=true;try{const result=statements.map(stmt=>execute(stmt.sql,stmt.values));sqlite.exec('COMMIT');insideBatch=false;if(afterRead){const action=afterRead;afterRead=null;action();}return result;}catch(error){insideBatch=false;sqlite.exec('ROLLBACK');throw error;}}};
 function insert(table,values){const keys=Object.keys(values);assert.match(table,/^[a-z_]+$/);sqlite.prepare('INSERT INTO '+table+'('+keys.join(',')+')VALUES('+keys.map(()=>'?').join(',')+')').run(...keys.map(key=>values[key]));}
 const env={DB:db,ADMIN_TIMEZONE:'Asia/Singapore'};async function api(path,{actor=owner,method='GET',body,operations=false}={}){const url=new URL('https://polish.synthetic.test/admin/api/'+(operations?'operations/':'')+path),request=new Request(url,{method,headers:{origin:url.origin,...(body?{'content-type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const response=operations?await handleOperationsApi(request,env,actor,url):await handleAdminApi(request,env,{},url,actor);assert.ok(response);const value=(response.headers.get('content-type')||'').includes('application/json')?await response.json():await response.text();return{status:response.status,value,response};}
 return{sqlite,db,env,trace,insert,api,afterNextRead(action){afterRead=action;},close(){sqlite.close();}};
}
function ok(result,status=200){assert.equal(result.status,status,JSON.stringify(result.value));return result.value;}
async function workspaceCall(store,path,{method='GET',body}={}){const url=new URL('https://polish.synthetic.test/admin/api/workspace/'+path),request=new Request(url,{method,headers:{origin:url.origin,...(body?{'content-type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})}),response=await handleWorkspaceExperience(request,store.env,owner,url);return{status:response.status,value:await response.json()};}
function zeros(){return Object.fromEntries(STAGES.map(stage=>[stage,0]));}
function expectedCounts(rows){const counts=zeros();for(const row of rows)counts[row.stage]++;return counts;}
function assertCounts(packet,expected){assert.deepEqual(packet.meta.stage_counts,expectedCounts(expected));assert.equal(Object.values(packet.meta.stage_counts).reduce((sum,n)=>sum+n,0),packet.meta.total);assert.equal(packet.meta.total,expected.length);}
function pipelineFixture(h){const at='2026-11-01T04:00:00.000Z';for(const id of ['CUS-A','CUS-B'])h.insert('crm_customers',{public_id:id,name:'Synthetic '+id,status:'active',owner_id:'owner',created_at:at,updated_at:at});let number=0;const rows=[];for(const[stage,count]of STAGES.map((stage,index)=>[stage,[31,9,7,5,3,2][index]]))for(let i=0;i<count;i++){const n=++number,row={public_id:'OPP-'+String(n).padStart(3,'0'),title:'Synthetic deal '+n,customer_id:n%3===0?'CUS-A':'CUS-B',stage,amount_minor:1000+n*100,currency:n%2?'EUR':'USD',probability:stage==='won'?100:stage==='lost'?0:25,owner_id:n%2?'OTHER':'owner',notes:n%2?'Other cohort':'机器视觉检测方案 Cohort A',created_at:at,updated_at:at,archived_at:null};h.insert('crm_opportunities',row);rows.push(row);}for(const[stage,i]of STAGES.map((stage,i)=>[stage,i])){const row={...rows[0],public_id:'ARCHIVED-'+i,title:'Archived '+stage,stage,probability:stage==='won'?100:stage==='lost'?0:25,archived_at:'2026-11-02T00:00:00.000Z'};h.insert('crm_opportunities',row);rows.push(row);}return rows;}

await test('pipeline stage totals cover the full filtered population rather than the twenty-five loaded cards',async()=>{const h=harness();try{const all=pipelineFixture(h),active=all.filter(row=>!row.archived_at);const first=ok(await h.api('opportunities?limit=25&page=1'));assert.equal(first.data.length,25);assertCounts(first,active);assert.equal(first.meta.total,57);assert.notDeepEqual(first.meta.stage_counts,expectedCounts(first.data));const last=ok(await h.api('opportunities?limit=25&page=3'));assert.equal(last.data.length,7);assertCounts(last,active);assert.deepEqual(last.meta.stage_counts,first.meta.stage_counts);const emptyPage=ok(await h.api('opportunities?limit=25&page=99'));assert.equal(emptyPage.data.length,0);assertCounts(emptyPage,active);}finally{h.close();}});
await test('pipeline stage counts use identical text, customer, owner, currency, amount and closed filters',async()=>{const h=harness();try{const all=pipelineFixture(h),options={q:'机器视觉检测方案',customer_id:'CUS-A',owner_id:'owner',currency:'USD',amount_min:'1500',amount_max:'6000',closed:'false',created_from:'2026-11-01',created_to:'2026-11-01'};const expected=all.filter(row=>!row.archived_at&&row.notes.includes(options.q)&&row.customer_id===options.customer_id&&row.owner_id===options.owner_id&&row.currency===options.currency&&row.amount_minor>=1500&&row.amount_minor<=6000&&!['won','lost'].includes(row.stage));assert.ok(expected.length>0);const packet=ok(await h.api('opportunities?'+query({...options,limit:2})));assertCounts(packet,expected);assert.ok(packet.data.every(row=>expected.some(candidate=>candidate.public_id===row.public_id)));const proposal=ok(await h.api('opportunities?'+query({stage:'proposal',currency:'USD'})));assertCounts(proposal,all.filter(row=>!row.archived_at&&row.stage==='proposal'&&row.currency==='USD'));for(const stage of STAGES)if(stage!=='proposal')assert.equal(proposal.meta.stage_counts[stage],0);}finally{h.close();}});
await test('pipeline archive, empty result and timezone boundaries remain consistent between totals and cards',async()=>{const h=harness();try{const all=pipelineFixture(h);assertCounts(ok(await h.api('opportunities?archived=true')),all.filter(row=>row.archived_at));assertCounts(ok(await h.api('opportunities?archived=all')),all);const empty=ok(await h.api('opportunities?q=NO-SYNTHETIC-RECORD-MATCHES'));assertCounts(empty,[]);const base={...all[0],stage:'qualification',amount_minor:1,created_at:'2026-10-31T15:59:59.999Z',updated_at:'2026-11-01T00:00:00.000Z'};h.insert('crm_opportunities',{...base,public_id:'BEFORE-SG-DAY'});h.insert('crm_opportunities',{...base,public_id:'AT-SG-DAY',created_at:'2026-10-31T16:00:00.000Z'});const result=ok(await h.api('opportunities?created_from=2026-11-01&created_to=2026-11-01&limit=100'));assertCounts(result,[...all.filter(row=>!row.archived_at),{...base,public_id:'AT-SG-DAY'}]);assert.equal(result.data.some(row=>row.public_id==='BEFORE-SG-DAY'),false);assert.equal((await h.api('opportunities?amount_min=1')).status,422);}finally{h.close();}});
await test('pipeline packet remains one coherent snapshot if another record is inserted while its reads are pending',async()=>{const h=harness();try{const all=pipelineFixture(h);h.afterNextRead(()=>h.insert('crm_opportunities',{...all[0],public_id:'CONCURRENT-INSERT',stage:'proposal',created_at:'2026-11-02T00:00:00.000Z'}));const packet=ok(await h.api('opportunities?limit=100'));assert.equal(h.sqlite.prepare("SELECT COUNT(*) n FROM crm_opportunities WHERE archived_at IS NULL").get().n,58);assertCounts(packet,all.filter(row=>!row.archived_at));assert.equal(packet.data.some(row=>row.public_id==='CONCURRENT-INSERT'),false);}finally{h.close();}});
await test('activity accepts separate occurred_at and direction parameters and sorts by business occurrence rather than insertion ID',async()=>{const h=harness();try{for(const[public_id,occurred_at]of [['ACT-NEWER','2026-11-03T00:00:00.000Z'],['ACT-OLDER','2026-11-01T00:00:00.000Z'],['ACT-TIE','2026-11-03T00:00:00.000Z']])h.insert('crm_activities',{public_id,type:'note',subject:public_id,actor_id:'owner',actor_name:'Synthetic owner',occurred_at,created_at:'2026-11-04T00:00:00.000Z'});const packet=ok(await h.api('activities?sort=occurred_at&dir=desc'));assert.deepEqual(packet.data.map(row=>row.public_id),['ACT-TIE','ACT-NEWER','ACT-OLDER']);assert.equal(packet.meta.stage_counts,undefined);for(const sort of ['occurred_at desc','-occurred_at','occurred_at;DROP TABLE crm_activities'])assert.equal((await h.api('activities?'+query({sort}))).status,422);assert.equal((await h.api('activities?sort=occurred_at&dir=sideways')).status,422);}finally{h.close();}});
await test('read-only roles can see pipeline counts without acquiring write or audit access',async()=>{const h=harness();try{const rows=pipelineFixture(h);assertCounts(ok(await h.api('opportunities?limit=3',{actor:viewer})),rows.filter(row=>!row.archived_at));assert.equal((await h.api('opportunities',{actor:null})).status,401);assert.equal((await h.api('audit',{actor:viewer})).status,403);assert.equal((await h.api('opportunities',{actor:viewer,method:'POST',body:{title:'Denied'}})).status,403);}finally{h.close();}});

function reportFixture(h){const at='2026-11-04T00:00:00.000Z';for(const id of ['source-a','source-b'])h.insert('ops_data_sources',{id,name:'Synthetic '+id,kind:'csv_generic',created_at:at,updated_at:at});const records=[
 ['REPORT-A','daily',{from:'2026-11-01',to:'2026-11-01',source_id:'source-a',currency:'USD'},'2020-01-01T00:00:00.000Z'],
 ['REPORT-WEEK','weekly',{from:'2026-10-29',to:'2026-11-04',source_id:'source-a',currency:'USD'},'2027-01-01T00:00:00.000Z'],
 ['REPORT-B','daily',{from:'2026-11-01',to:'2026-11-01',source_id:'source-b',currency:'USD'},at],
 ['REPORT-EUR','daily',{from:'2026-11-01',to:'2026-11-01',source_id:'source-a',currency:'EUR'},at],
 ['REPORT-ALL','daily',{from:'2026-11-01',to:'2026-11-01',source_id:'',currency:''},at],
 ['REPORT-OLD','daily',{from:'2026-10-01',to:'2026-10-01',source_id:'source-a',currency:'USD'},at],
 ['REPORT-INVERTED','daily',{from:'2026-11-03',to:'2026-11-01',source_id:'source-a',currency:'USD'},at],
 ['REPORT-INVALID-DAY','daily',{from:'2026-02-30',to:'2026-11-01',source_id:'source-a',currency:'USD'},at],
 ['REPORT-LEGACY','daily','{',at],
 ];for(const[id,type,filters,created_at]of records)h.insert('ops_reports',{id,type,title:'Synthetic '+id,language:'en',filters_json:typeof filters==='string'?filters:JSON.stringify(filters),summary_json:'{}',content_markdown:'# Synthetic saved report',rules_snapshot_json:'[]',created_by:'owner',created_at});return records;}
await test('saved report filters use inclusive coverage overlap and exact generation source and currency rather than creation time',async()=>{const h=harness();try{reportFixture(h);const packet=ok(await h.api('reports?'+query({from:'2026-11-01',to:'2026-11-02',source_id:'source-a',currency:'USD'}),{operations:true}));assert.deepEqual(packet.data.map(row=>row.id),['REPORT-WEEK','REPORT-A']);assert.equal(packet.meta.total,2);assert.equal(packet.meta.date_basis,'saved_coverage_overlap');assert.equal(packet.meta.source_currency_basis,'exact_saved_generation_scope');assert.ok(packet.data.every(row=>row.filters.source_id==='source-a'&&row.filters.currency==='USD'));assert.ok(packet.data.some(row=>row.created_at.startsWith('2020')));assert.ok(packet.data.some(row=>row.created_at.startsWith('2027')));assert.equal(packet.data.some(row=>row.id==='REPORT-ALL'),false);}finally{h.close();}});
await test('report counts and pagination share scope, optional date bounds work and invalid saved periods cannot borrow creation dates',async()=>{const h=harness();try{reportFixture(h);const filters={source_id:'source-a',currency:'USD',from:'2026-11-01',to:'2026-11-02',limit:1};const first=ok(await h.api('reports?'+query({...filters,page:1}),{operations:true})),second=ok(await h.api('reports?'+query({...filters,page:2}),{operations:true})),third=ok(await h.api('reports?'+query({...filters,page:3}),{operations:true}));assert.equal(first.meta.total,2);assert.equal(second.meta.total,2);assert.equal(first.meta.pages,2);assert.notEqual(first.data[0].id,second.data[0].id);assert.equal(third.data.length,0);assert.equal(third.meta.total,2);const single=ok(await h.api('reports?'+query({source_id:'source-a',currency:'USD',from:'2026-11-02'}),{operations:true}));assert.deepEqual(single.data.map(row=>row.id),['REPORT-WEEK']);const daily=ok(await h.api('reports?'+query({...filters,type:'daily',limit:25}),{operations:true}));assert.deepEqual(daily.data.map(row=>row.id),['REPORT-A']);const noDate=ok(await h.api('reports?limit=50',{operations:true}));assert.equal(noDate.data.length,9);assert.equal(noDate.meta.filters.from,'');assert.equal(noDate.meta.filters.to,'');}finally{h.close();}});
await test('report scope validation rejects malformed range, currency, source and unsupported query fields',async()=>{const h=harness();try{reportFixture(h);for(const args of [{from:'2026-02-30'},{from:'2026-11-04',to:'2026-11-01'},{currency:'NOT-A-CURRENCY'},{type:'constructor'},{source_id:'not-a-source'},{unknown:'ignored'}]){const result=await h.api('reports?'+query(args),{operations:true});assert.ok(result.status>=400&&result.status<500,JSON.stringify({args,status:result.status,value:result.value}));}}finally{h.close();}});

