async function crmListHarness({lang='en',resource='customers',demo=false,storage=new Map(),role='owner',iconMarkup=()=>''}={}){const previous={document:globalThis.document,FormData:globalThis.FormData,localStorage:globalThis.localStorage},document=new HtmlNode('document'),body=new HtmlNode('body'),page=new HtmlNode(),tool=new HtmlNode('dialog'),requests=[],navigations=[],storageCalls=[],core=coreHarness(lang,{role}).core;tool.setAttribute('id','crm-tool-dialog');tool.className='crm-tool-dialog';document.body=body;document.append(body);body.append(page,tool);document.createElement=tag=>new HtmlNode(tag);document.getElementById=id=>document.querySelector('#'+id);document.activeElement=body;globalThis.document=document;globalThis.localStorage={getItem:key=>{storageCalls.push({type:'get',key});return storage.get(key)??null;},setItem:(key,value)=>{storageCalls.push({type:'set',key});storage.set(key,String(value));}};globalThis.FormData=class{constructor(form){this.rows=form.querySelectorAll('input,select,textarea').filter(node=>node.name&&!node.disabled&&(!['checkbox','radio'].includes(node.getAttribute('type'))||node.checked)).map(node=>[node.name,node.tagName==='select'&&!node.value?(node.querySelectorAll('option').find(option=>option.selected)||node.querySelector('option'))?.value||'':node.value]);}get(key){return this.rows.find(([name])=>name===key)?.[1]??null;}getAll(key){return this.rows.filter(([name])=>name===key).map(([,value])=>value);}[Symbol.iterator](){return this.rows.values();}};const state=core.state;state.tab=resource==='customers'?'customers':'tasks';state.params=new URLSearchParams();state.testMode=demo;state.principal={id:'owner',name:'Synthetic owner',role};const rows=[1,2].map(index=>({public_id:'CRM-IDENTITY-'+index,name:resource==='customers'?'Named customer '+index:undefined,title:resource==='tasks'?'Named task '+index:undefined,status:resource==='customers'?'active':'open',priority:'normal',version:1,owner_id:'owner',created_at:'2026-11-01T00:00:00.000Z'})),legacy={id:'LEGACY-'+resource,name:'Legacy owner-only view',resource,owner_id:'owner',visibility:'private',version:1,config:{columns:['owner_id','owner_id'],sort:'created_at',dir:'desc'}};const controller=createCrmExperienceController({state,api:async(path,options={})=>{requests.push({path,options});if(path.startsWith('workspace/views?'))return{data:[structuredClone(legacy)]};if(path==='workspace/views'&&options.method==='POST')return{data:{id:'SAVED-'+resource,owner_id:'owner',version:1,...structuredClone(options.body)}};throw Error('Unexpected synthetic CRM view request '+path);},esc:value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),t:core.t,money:String,date:String,icon:iconMarkup,navigate:(tab,params)=>navigations.push({tab,params:new URLSearchParams(params)}),toast(){},can:permission=>role!=='viewer'||permission==='read',confirmAction:async()=>true,openRecord(){}});return{state,page,tool,document,rows,requests,navigations,storageCalls,async load(params=''){state.params=new URLSearchParams(params);page.innerHTML='<div class="data-panel">'+core.renderTable(state.tab,rows)+'</div>';await controller.decorateList({tab:state.tab,resource,result:{data:rows,meta:{total:2}},page});},async fire(node,type='click'){const event=node.dispatch(type);await Promise.all(event.pending);await new Promise(resolve=>setImmediate(resolve));return event;},close(){controller.discardChanges();for(const[key,value]of Object.entries(previous)){if(value===undefined)delete globalThis[key];else globalThis[key]=value;}}};}
